fn count_digits(text: &Vec<char>) -> usize {
    let mut count: usize = 0;
    for &ch in text.iter() {
        // ASCII decimal digits are '0'..='9' (codes 48..=57)
        if ('0'..='9').contains(&ch) {
            count += 1;
        }
    }
    count
}